-- Q 2026-10-25 (thread "Tank buff และปรับเด็ค"): 6 Tank slot cards that heal the moment they're drawn into slot N (onDraw + enteredAt).
-- Needs the engine from the same PR (onDraw now checks its conditions). Heal 4 + 4% Max HP, Q tunes in Admin.
update public.cards set effect = $t$Comes into play, if this card was drawn into slot 1: Gain 4 HP, gain 4% of your Max HP as HP$t$, effect_json = $t$[{"hook": "onDraw", "if": [{"c": "enteredAt", "n": 1}], "do": [{"a": "heal", "who": "self", "n": 4}, {"a": "heal", "who": "self", "n": 4, "per": "maxHpPct"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-001';
update public.cards set effect = $t$Comes into play, if this card was drawn into slot 2: Gain 4 HP, gain 4% of your Max HP as HP$t$, effect_json = $t$[{"hook": "onDraw", "if": [{"c": "enteredAt", "n": 2}], "do": [{"a": "heal", "who": "self", "n": 4}, {"a": "heal", "who": "self", "n": 4, "per": "maxHpPct"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-002';
update public.cards set effect = $t$Comes into play, if this card was drawn into slot 3: Gain 4 HP, gain 4% of your Max HP as HP$t$, effect_json = $t$[{"hook": "onDraw", "if": [{"c": "enteredAt", "n": 3}], "do": [{"a": "heal", "who": "self", "n": 4}, {"a": "heal", "who": "self", "n": 4, "per": "maxHpPct"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-003';
update public.cards set effect = $t$Comes into play, if this card was drawn into slot 4: Gain 4 HP, gain 4% of your Max HP as HP$t$, effect_json = $t$[{"hook": "onDraw", "if": [{"c": "enteredAt", "n": 4}], "do": [{"a": "heal", "who": "self", "n": 4}, {"a": "heal", "who": "self", "n": 4, "per": "maxHpPct"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-011';
update public.cards set effect = $t$Comes into play, if this card was drawn into slot 5: Gain 4 HP, gain 4% of your Max HP as HP / Before action, if you play Charge and opponent plays Strike: Gain Parry 1 next turn (the first 1 hit past Block is parried: 0 dmg)$t$, effect_json = $t$[{"hook": "onDraw", "if": [{"c": "enteredAt", "n": 5}], "do": [{"a": "heal", "who": "self", "n": 4}, {"a": "heal", "who": "self", "n": 4, "per": "maxHpPct"}]}, {"do": [{"a": "status", "n": 1, "who": "self", "kind": "parry", "turns": 1}], "if": [{"a": "charge", "c": "selfAction"}, {"a": "strike", "c": "enemyAction"}], "hook": "modify"}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-012';
update public.cards set effect = $t$Comes into play, if this card was drawn into slot 1: Gain 4 HP, gain 4% of your Max HP as HP$t$, effect_json = $t$[{"hook": "onDraw", "if": [{"c": "enteredAt", "n": 1}], "do": [{"a": "heal", "who": "self", "n": 4}, {"a": "heal", "who": "self", "n": 4, "per": "maxHpPct"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-015';
